// NewAddWorkitemsPayload builds a Milestones service add_workitems endpoint
// payload.
func NewAddWorkitemsPayload(body *AddWorkitemsRequestBody, slug string, projectID string, milestoneID string, credential *string) *milestones.AddWorkitemsPayload {
	v := &milestones.MilestoneIssues{}
	if body.Issues != nil {
		v.Issues = make([]string, len(body.Issues))
		for i, val := range body.Issues {
			actual, ok := val.Value()
			if !ok {
				continue
			}
			v.Issues[i] = actual
		}
	} else {
		v.Issues = nil
	}
	if actual, ok := body.RequestID.Value(); ok {
		vRequestIDValue := actual

		v.RequestID = &vRequestIDValue
	}
	if actual, ok := body.ExpectedRevision.Value(); ok {
		vExpectedRevisionValue := actual

		v.ExpectedRevision = &vExpectedRevisionValue
	}
	res := &milestones.AddWorkitemsPayload{
		Body: v,
	}
	res.Slug = slug
	res.ProjectID = projectID
	res.MilestoneID = milestoneID
	res.Credential = credential

	return res
}

